style.css:
@-moz-document domain("roblox.com") {
/* Main Background & Headers */
    body, 
    .content, 
    #container-main, 
    .dark-theme, 
    .light-theme,
    .gui-header,
    .navigation,
    .rbx-header {
        background-color: #1a0202 !important; /* Deep dark red background */
        color: #000000 !important;             /* Black text */
    }

    /* Cards, Panels & Containers */
    .section-content, 
    .item-card-container, 
    .game-card-container, 
    .v2-game-card-container,
    .profile-header, 
    .slide-item-container,
    .menu-vertical,
    .chat-main {
        background-color: #2b0505 !important; /* Slightly lighter red for contrast */
        border-color: #3d0808 !important;
        color: #000000 !important;
    }

    /* Text & Links Override */
    p, span, h1, h2, h3, h4, h5, h6, a, div, 
    .text-name, .text-lead, .text-label, 
    .game-card-name, .item-card-name {
        color: #000000 !important; /* Pure black text across all elements */
    }

    /* Inputs & Search Bars */
    input, textarea, select, .form-control {
        background-color: #3d0808 !important;
        color: #000000 !important;
        border: 1px solid #000000 !important;
    }

    /* Buttons */
    .btn-primary-md, .btn-secondary-md, .btn-control-md {
        background-color: #4a0000 !important;
        color: #000000 !important;
        border: 1px solid #000000 !important;
    }

    /* Navigation Sidebar */
    #navigation {
        background-color: #120101 !important;
    }
}
